# Better strategy: parts separated by commas; check if each part STARTS with title case content.
# But the first cat may be embedded in a phrase like "for X". Let's also extract the last 1-2 capitalized words of each comma-part as candidate.

def extract_cats_v2(desc):
    parts = re.split(r",\s*", desc)
    # For each part: strip leading "and " / "or ", then strip leading lowercase words.
    # Then check if remaining is a title case phrase.
    cleaned = []
    for p in parts:
        p_clean = p.strip().rstrip(".")
        # Remove leading "and" / "or"
        p_clean = re.sub(r"^(?:and|or)\s+", "", p_clean)
        # Strip everything up to the LAST occurrence of a lowercase word followed by a capital, retaining title case.
        # i.e., find the last position where a Title Case run begins.
        # Match: from the end, take title-case-only suffix
        m = re.search(r"(?:[A-Z][A-Za-z&/()'\-]*(?:\s+[A-Z][A-Za-z&/()'\-]*)*)$", p_clean)
        if m:
            candidate = m.group(0)
            # Must be reasonable length
            if len(candidate.split()) <= 6 and len(candidate) >= 3:
                cleaned.append(candidate)
            else:
                cleaned.append(None)
        else:
            cleaned.append(None)

    # Find longest run of consecutive non-None
    runs = []
    current = []
    for c in cleaned:
        if c is not None:
            current.append(c)
        else:
            if len(current) >= 2:
                runs.append(current)
            current = []
    if len(current) >= 2:
        runs.append(current)
    if not runs:
        return []
    return max(runs, key=len)

